// Keep the combination picker separate from the full-table filters.
function filterReactionRows({size='',element='',effect=''}={}){
 const effects=new Set(['dot','slow','stun','pull','chain','vuln','heal','mana']);
 return Object.values(REACTIONS).filter(r=>(!size||r.elements.length===Number(size))&&(element===''||r.elements.includes(Number(element)))&&(!effect||(effects.has(effect)&&r[effect]>0))).sort((a,b)=>a.key.length-b.key.length||a.key.localeCompare(b.key));
}
function reactionRowsHtml(rows){return rows.map(r=>'<tr><td>'+elementBadges(r.elements)+'</td><td>'+r.name+'</td><td>'+reactionDescription(r)+'</td></tr>').join('')||'<tr><td colspan="3">条件に合う反応はありません。</td></tr>';}
reactionTableHtml=()=>'<div class="reaction-table-filters"><label>属性数<select id="reactionFilterSize" aria-label="反応の属性数" onchange="updateReactionTable()"><option value="">すべて</option><option value="2">2属性</option><option value="3">3属性</option></select></label><label>含む属性<select id="reactionFilterElement" aria-label="含む属性" onchange="updateReactionTable()"><option value="">すべて</option>'+ELEMENTS.map((e,i)=>'<option value="'+i+'">'+e.icon+' '+e.name+'</option>').join('')+'</select></label><label>効果<select id="reactionFilterEffect" aria-label="反応の効果" onchange="updateReactionTable()"><option value="">すべて</option>'+[['dot','継続ダメージ'],['slow','減速'],['stun','拘束'],['pull','吸引'],['chain','連鎖追撃'],['vuln','被ダメージ増加'],['heal','HP回復'],['mana','MP回復']].map(([key,name])=>'<option value="'+key+'">'+name+'</option>').join('')+'</select></label><button onclick="resetReactionTableFilters()">絞り込み解除</button></div><p id="reactionFilterCount" role="status" aria-live="polite">84 / 84種類</p><table class="reaction-table"><thead><tr><th scope="col">属性</th><th scope="col">反応</th><th scope="col">効果</th></tr></thead><tbody id="reactionFilteredRows">'+reactionRowsHtml(filterReactionRows())+'</tbody></table>';
function updateReactionTable(){const body=$('reactionFilteredRows');if(!body)return;const rows=filterReactionRows({size:$('reactionFilterSize').value,element:$('reactionFilterElement').value,effect:$('reactionFilterEffect').value});body.innerHTML=reactionRowsHtml(rows);$('reactionFilterCount').textContent=rows.length+' / '+Object.keys(REACTIONS).length+'種類';}
function resetReactionTableFilters(){for(const id of ['reactionFilterSize','reactionFilterElement','reactionFilterEffect']){const el=$(id);if(el)el.value='';}updateReactionTable();}
const filteredReactionGuideBase=showReactionGuide;showReactionGuide=(...args)=>{const result=filteredReactionGuideBase(...args),hint=$('card').querySelector('.panel-controls');if(hint)hint.textContent='十字キー：項目移動　A：選択を開く／確定　B：戻る　X：閉じる　右スティック：スクロール';return result;};
const filteredReactionPadBase=padMenu;padMenu=(g,l,r,dt)=>{if(menuSurface==='reactions'&&!menuSelectDialog&&$('reactionTable')&&!$('reactionTable').hidden&&padEdge(g,'back')){reactionGuideBack();return;}return filteredReactionPadBase(g,l,r,dt);};
